package spiring.exapmle.apigateway.client;

import com.fitness.booking.grpc.*; import com.fitness.user.grpc.*; import com.fitness.workout.grpc.*;
import org.springframework.context.annotation.Primary; import org.springframework.stereotype.Service; import spiring.exapmle.apigateway.dto.*; import java.util.List;
@Service @Primary
public class GrpcBookingServiceClient implements BookingServiceClient {
 private final BookingServiceGrpc.BookingServiceBlockingStub grpc; private final UserServiceGrpc.UserServiceBlockingStub users; private final WorkoutServiceGrpc.WorkoutServiceBlockingStub workouts;
 public GrpcBookingServiceClient(BookingServiceGrpc.BookingServiceBlockingStub grpc,UserServiceGrpc.UserServiceBlockingStub users,WorkoutServiceGrpc.WorkoutServiceBlockingStub workouts){this.grpc=grpc;this.users=users;this.workouts=workouts;}
 public List<BookingDto> getBookings(Long c,Long w){return grpc.getBookings(ListBookingsRequest.newBuilder().setIdClient(n(c)).setIdWorkout(n(w)).build()).getBookingsList().stream().map(this::booking).toList();}
 public BookingDto getBooking(Long id){return booking(grpc.getBooking(GetBookingRequest.newBuilder().setIdBooking(id).build()));}
 public List<BookingDto> getBookingsByClient(Long id,String status){return getBookingsByClient(id,status,null,null);}
 public List<BookingDto> getBookingsByClient(Long id,String status,String sort,String order){return grpc.getClientBookings(GetClientBookingsRequest.newBuilder().setIdClient(n(id)).setStatus(v(status)).setSortBy(v(sort)).setSortOrder(v(order)).build()).getBookingsList().stream().map(this::booking).toList();}
 public List<SubscriptionDto> getSubscriptionsByClient(Long id){return grpc.getClientSubscriptions(GetClientSubscriptionsRequest.newBuilder().setIdClient(id).build()).getSubscriptionsList().stream().map(this::subscription).toList();}
 public SubscriptionDto getSubscription(Long id){return subscription(grpc.getSubscription(GetSubscriptionRequest.newBuilder().setIdSubscription(id).build()));}
 public List<PaymentDto> getPaymentsByClient(Long id,String from,String to){return grpc.getClientPayments(GetClientPaymentsRequest.newBuilder().setIdClient(id).setDateFrom(v(from)).setDateTo(v(to)).build()).getPaymentsList().stream().map(this::payment).toList();}
 public BookingDto bookWorkout(Long client,Long workout){return booking(grpc.bookWorkout(BookWorkoutRequest.newBuilder().setIdClient(clientId(client)).setIdWorkout(workout).build()));}
 public BookingDto cancelBooking(Long client,Long id){return booking(grpc.cancelBooking(CancelBookingRequest.newBuilder().setIdClient(clientId(client)).setIdBooking(id).build()));}
 private BookingDto booking(com.fitness.booking.grpc.BookingResponse x){BookingDto d=new BookingDto();d.setIdBooking(x.getIdBooking());d.setStatus(x.getStatus().name());d.setBookingDate(x.getBookingDate());try{d.setClient(GrpcUserServiceClient.client(users.getClient(GetClientRequest.newBuilder().setIdClient(x.getIdClient()).build())));}catch(RuntimeException ignored){}try{WorkoutResponse w=workouts.getWorkout(GetWorkoutRequest.newBuilder().setIdWorkout(x.getIdWorkout()).build());WorkoutDto wd=new WorkoutDto();wd.setIdWorkout(w.getIdWorkout());wd.setStartDatetime(w.getStartDatetime());wd.setDuration(w.getDuration());wd.setStatus(w.getStatus().name());wd.setMaxCapacity(w.getMaxCapacity());ProgramResponse p=workouts.getTrainingProgram(GetProgramRequest.newBuilder().setIdProgram(w.getIdTrainingProgram()).build());TrainingProgramDto pd=new TrainingProgramDto();pd.setIdTrainingProgram(p.getIdTrainingProgram());pd.setName(p.getName());pd.setDescription(p.getDescription());pd.setType(p.getType());pd.setDifficultyLevel(p.getDifficultyLevel());pd.setDuration(p.getDuration());try{pd.setTrainer(GrpcUserServiceClient.trainer(users.getTrainer(GetTrainerRequest.newBuilder().setIdTrainer(p.getIdTrainer()).build())));}catch(RuntimeException ignored){}wd.setTrainingProgram(pd);try{wd.setTrainer(GrpcUserServiceClient.trainer(users.getTrainer(GetTrainerRequest.newBuilder().setIdTrainer(w.getIdTrainer()).build())));}catch(RuntimeException ignored){}d.setWorkout(wd);}catch(RuntimeException ignored){}return d;}
 private SubscriptionDto subscription(com.fitness.booking.grpc.SubscriptionResponse x){SubscriptionDto d=new SubscriptionDto();d.setIdSubscription(x.getIdSubscription());d.setSubscriptionTypeId(x.getSubscriptionTypeId());d.setStartDate(x.getStartDate());d.setEndDate(x.getEndDate());d.setStatus(x.getStatus());d.setRemainingSessions(x.getRemainingSessions());try{d.setClient(GrpcUserServiceClient.client(users.getClient(GetClientRequest.newBuilder().setIdClient(x.getIdClient()).build())));}catch(RuntimeException ignored){}return d;}
 private PaymentDto payment(com.fitness.booking.grpc.PaymentResponse x){PaymentDto d=new PaymentDto();d.setIdPayment(x.getIdPayment());d.setAmount((float)x.getAmount());d.setPaymentDate(x.getPaymentDate());d.setStatus(x.getStatus().name());try{d.setClient(GrpcUserServiceClient.client(users.getClient(GetClientRequest.newBuilder().setIdClient(x.getIdClient()).build())));}catch(RuntimeException ignored){}return d;}
 private static long n(Long x){return x==null?0:x;}private static String v(String x){return x==null?"":x;}
 public SubscriptionDto createSubscription(Long clientId,CreateSubscriptionInputDto input){return subscription(grpc.createSubscription(CreateSubscriptionRequest.newBuilder().setIdClient(clientId(clientId)).setSubscriptionTypeId(input.getSubscriptionTypeId()==null?0:input.getSubscriptionTypeId()).setStartDate(v(input.getStartDate())).build()));}
 public SubscriptionDto changeSubscriptionStatus(Long id,String status){return subscription(grpc.changeSubscriptionStatus(ChangeSubscriptionStatusRequest.newBuilder().setIdSubscription(id).setStatus(v(status)).build()));}
 public PaymentDto registerPayment(Long clientId,RegisterPaymentInputDto input){return payment(grpc.registerPayment(RegisterPaymentRequest.newBuilder().setIdClient(clientId(clientId)).setAmount(input.getAmount()==null?0.0:input.getAmount().doubleValue()).setIdSubscription(n(input.getIdSubscription())).setPaymentDate(v(input.getPaymentDate())).build()));}
 private long clientId(Long id){return users.getClientByUser(GetClientByUserRequest.newBuilder().setIdUser(n(id)).build()).getIdClient();}
}
